let lockBoard,firstCard,secondCard,hasFlippedCard=!1;const CARDS=document.querySelectorAll(".memory-card");function flipCard(){if(!lockBoard&&this!==firstCard){if(this.classList.add("flip"),!hasFlippedCard)return hasFlippedCard=!0,void(firstCard=this);secondCard=this,checkForMatch()}}function checkForMatch(){firstCard.dataset.team===secondCard.dataset.team?disableCards():unflipCards()}function disableCards(){firstCard.removeEventListener("click",flipCard),secondCard.removeEventListener("click",flipCard),resetBoard()}function unflipCards(){lockBoard=!0,setTimeout((()=>{firstCard.classList.remove("flip"),secondCard.classList.remove("flip"),resetBoard()}),1500)}function resetBoard(){hasFlippedCard=!1,lockBoard=!1,firstCard=null,secondCard=null}CARDS.forEach((r=>{let a=Math.floor(64*Math.random());r.style.order=a})),CARDS.forEach((r=>r.addEventListener("click",flipCard)));